import torch

def analyze_maze(file_path):
    try:
        # Load the PyTorch serialized data
        data = torch.load(file_path)

        # Check the type of data
        data_type = type(data)

        # Get additional information if it's a known PyTorch object
        if isinstance(data, torch.nn.Module):
            info = {
                "object_type": "nn.Module",
                "layer_count": len(list(data.named_modules())),
                "layers": list(data.named_modules()),
            }
        elif isinstance(data, torch.Tensor):
            info = {
                "object_type": "tensor",
                "shape": data.size(),
                "dtype": data.dtype,
                "contents": data.tolist(),
            }
        elif isinstance(data, dict):
            info = {
                "object_type": "dictionary",
                "keys": list(data.keys()),
            }
        else:
            info = {
                "object_type": "unknown",
            }

        return {
            "data_type": data_type,
            "info": info
        }
    except Exception as e:
        return {
            "error": str(e)
        }

if __name__ == "__main__":
    file_path = "/home/ctfplayer/ctf_files/attachment/maze.pt"
    analysis = analyze_maze(file_path)
    print(analysis)

