import pickle
import sys
import pprint

def read_pickle(file_path):
    try:
        with open(file_path, "rb") as f:
            data = pickle.load(f)

        # Pretty print the data to inspect
        with open("/home/ctfplayer/ctf_files/pickle_contents.txt", "w") as output_file:
            pprint.pprint(data, output_file)

        print("[+] Pickle data has been written to pickle_contents.txt")
    except Exception as e:
        print(f"[-] Failed to read pickle file: {e}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python read_pickle.py <path_to_pickle_file>")
    else:
        read_pickle(sys.argv[1])
